-- Opaque customer-facing links for paying issued sales invoices with MartPoint Pay.
-- Tokens are generated by the application per invoice and are not guessable IDs.
SET @mp_invoice_pay_col := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='db_sales'
    AND COLUMN_NAME='invoice_payment_token'
);
SET @mp_invoice_pay_sql := IF(@mp_invoice_pay_col=0,
  'ALTER TABLE `db_sales` ADD COLUMN `invoice_payment_token` CHAR(64) NULL DEFAULT NULL',
  'SELECT 1'
);
PREPARE mp_invoice_pay_stmt FROM @mp_invoice_pay_sql;
EXECUTE mp_invoice_pay_stmt;
DEALLOCATE PREPARE mp_invoice_pay_stmt;

SET @mp_invoice_pay_idx := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='db_sales'
    AND INDEX_NAME='uk_sales_invoice_payment_token'
);
SET @mp_invoice_pay_sql := IF(@mp_invoice_pay_idx=0,
  'ALTER TABLE `db_sales` ADD UNIQUE KEY `uk_sales_invoice_payment_token` (`invoice_payment_token`)',
  'SELECT 1'
);
PREPARE mp_invoice_pay_stmt FROM @mp_invoice_pay_sql;
EXECUTE mp_invoice_pay_stmt;
DEALLOCATE PREPARE mp_invoice_pay_stmt;
